import type { CloseReading, InlineGlossary } from '../types/closeReading';
import type { ReadingQuestion } from '../types/readingQuestion';
import { cet4CommonInlineGlossaryWords } from './cet4CommonInlineGlossary';

const close = (text: string, translation: string): CloseReading => ({
  translation, vocabulary: [],
  structure: { pattern: '段落整体理解', explanation: '本段以完整信息块呈现，先整体把握主旨，再结合上下文理解细节。' },
  highlights: [{ role: 'complement', text }],
});

const question = (number: number, prompt: string, answer: 'A' | 'B' | 'C' | 'D', evidence: string, options: readonly [string, string][]): ReadingQuestion => ({
  number, prompt, answer, evidence,
  analysis: `原文指出“${evidence}”，因此第 ${number} 题选择 ${answer}。`,
  closeReading: close(prompt, `题目要求判断：${prompt}`),
  options: options.map(([key, text]) => ({ key: key as 'A' | 'B' | 'C' | 'D', text, explanation: key === answer ? '该选项与原文依据相符。' : '该选项与原文依据不符。' })),
});

